mapper.select:
select substr(sm.message_num, 1, 2) as "message_class_cd" ,sm.message_type_cd as "message_type_cd" ,sm.message_num as "message_num" ,sm.message_text_ko as "message_text_ko" ,sm.message_text_en as "message_text_en" ,sm.message_text_zh as "message_text_zh" ,sm.message_text_ja as "message_text_ja" ,sm.message_text_ot as "message_text_ot" ,sm.remark as "remark" from sys_message sm where 1=1
and substr(sm.message_num, 1, 2) = #{message_class_cd}
and sm.message_type_cd = #{message_type_cd}
and sm.message_text_ko like #{message_text_ko} || '%'
order by sm.message_num
